// Flat plane: 0, Cylinder: 1, Log-polar: 2.
#define TRANSFORM 0

// Papper sheen. Interesting, but takes away from the shadows.
//#define HIGHLIGHT

// Color scheme - Dry terrain and water: 0, Coral: 1, Greyscale: 2, Flat white: 3.
#define COLOR 1

// The vertices. Mainly there for debug purposes.
//#define SHOW_VERTS



// 2 PI.
#define TAU 6.2831853


// Pointed top hexagon.
const vec2 s = vec2(1, 1.732);

// Vertices: Clockwise from the bottom left.

// Multiplied by 12 to give integer entries only.
const vec2[6] vID = vec2[6](vec2(-6, -2), vec2(-6, 2), vec2(0, 4), 
                      vec2(6, 2), vec2(6, -2), vec2(0, -4));

const vec2[6] eID = vec2[6](vec2(-6, 0), vec2(-3, 3), vec2(3, 3), vec2(6, 0), 
                      vec2(3, -3), vec2(-3, -3));



// Hexagonal bound: Not technically a distance function, but it's
// good enough for this example.
float getHex(vec2 p){

    // Pointed top hexagon.

    return max(dot(abs(p.xy), s/2.), abs(p.x*s.x));

}

// Hexagonal grid coordinates. This returns the local coordinates and the cell's center.
// The process is explained in more detail here:
//
// Minimal Hexagon Grid - Shane
// https://www.shadertoy.com/view/Xljczw
//
vec4 getGrid(vec2 p){

    vec4 ip = floor(vec4(p/s, p/s - .5));
    vec4 q = p.xyxy - vec4(ip.xy + .5, ip.zw + 1.)*s.xyxy;
    // The ID is multiplied by 12 to account for the inflated neighbor IDs above.
    return dot(q.xy, q.xy)<dot(q.zw, q.zw)? vec4(q.xy, ip.xy*12.) : vec4(q.zw, ip.zw*12. + 6.);
    //return getHex(q.xy)<getHex(q.zw)? vec4(q.xy, ip.xy) : vec4(q.zw, ip.zw + .5);

}
 mat2 rot2(in float a){ float c = cos(a), s = sin(a); return mat2(c, -s, s, c); }

float hash21(vec2 p){ 

    //return fract(sin(dot(p, vec2(27.617, 57.643)))*43758.5453); 

    // Dave Hoskin's hash formula, here:
    // https://www.shadertoy.com/view/4djSRW
    vec3 p3 = fract(vec3(p.xyx)*2.1031);
    p3 += dot(p3, p3.yzx + 43.123);
    return fract((p3.x + p3.y)*p3.z);
}




float boxLine(vec2 p, vec2 a, vec2 b) {

    float l = length(b - a)/2.;
    vec2 n = normalize(b - a); //(b - a)/(l*2.);//
    p -= a;
    return abs(dot(p, vec2(n.y, -n.x))) + step(l, abs(dot(p, n) - l));
}


// Unsigned distance to the segment joining "a" and "b".
float distLine(vec2 p, vec2 a, vec2 b){
  p*=rot2(iTime);
    p -= a; b -= a;
    float h = clamp(dot(p, b)/dot(b, b), 0., 1.);
    return length(p - b*h);
}

// Signed distance to a line passing through A and B.
float distLineS(vec2 p, vec2 a, vec2 b){
  p*=rot2(iTime);
   b -= a; 
   return dot(p - a, vec2(-b.y, b.x)/length(b));
}


// Compact, self-contained version of IQ's 2D value noise function.
float n2D(vec2 p){
 p.x+=cos(iTime);
    p.y+=sin(iTime);
    // Setup.
    // Any random integers will work, but this particular
    // combination works well.
    const vec2 s = vec2(1, 113);
    // Unique cell ID and local coordinates.
    vec2 ip = floor(p); p -= ip;
    // Vertex IDs.
    vec4 h = vec4(10., s.x, s.y, s.x + s.y) + dot(ip, s);
      p*=rot2(iTime);
    // Smoothing.
    p = p*p*(5. - 2.*p);
    //p *= p*p*(p*(p*6. - 15.) + 10.); // Smoother.
      p*=rot2(iTime);   p*=rot2(iTime);
      p.x+=cos(iTime);
    p.y+=sin(iTime);
    // Random values for the square vertices. The modulo is only there to 
    // accomodate my annoying AMD card that can't seem to wrap sinusoidals.
    h = fract(sin(mod(h, 6.2831853))*43758.5453);

    // Interpolation.
    h.xy = mix(h.xy, h.zw, p.y);
    return mix(h.x, h.y, p.x); // Output: Range: [0, 1].
}

// FBM -- 4 accumulated noise layers of modulated amplitudes and frequencies.
float fbm(vec2 p){ return n2D(p)*.533 + n2D(p*2.)*.267 + n2D(p*4.)*.133 + n2D(p*8.)*.067; }


// Tile color.
vec4 getCol(vec2 ip, vec2 uv){

    // Random Earthtone colors.
    float cRnd = hash21(ip + .21);
    vec3 col = .5 + .45*cos(6.2831*hash21(ip)/4. + vec3(0, 1, 2));
    #if COLOR == 0
    // Water color.
    if(cRnd<.35) col = mix(col, col.zyx, 1. - cRnd/2.);
    #else
    // Coral color.
    if(cRnd<.35)  col = mix(col, col.xzy, (1. - cRnd/2.)/2.);
    #endif

    // Ramping the color up a bit.
    col = pow(col, vec3(1.35))*1.35;

    //vec3 col2 = mix(col, col.yzx, 1. - cRnd/2.);
    //vec3 col3 = mix(col, col.xxx, 1. - cRnd/2.);
    ///if(hash21(ip + .35)<.35) col2 = col3;

    // Random blinking highlights.
    float bRnd = hash21(ip + .14);
    col = mix(col, col*1.2 + .25, smoothstep(.92, .97, sin(TAU*bRnd + iTime)));

    // Tile height, based on the color's greyscale value.
    float h = dot(col, vec3(.299, .587, .114));

    // Gradient.
    //col = mix(col, col.yzx, smoothstep(.2, .8, uv.x*.4 - uv.y + .3));    

    // Tile color and height.
    return vec4(col, h);
}
vec3 palette( float t ) {
    vec3 a = vec3(0.5, 0.5, 0.5);
    vec3 b = vec3(0.5, 0.5, 0.5);
    vec3 c = vec3(1.0, 1.0, 1.0);
    vec3 d = vec3(0.263,0.416,0.557);

    return a + b*cos( 6.28318*(c*t+d) );
}

void mainImage(out vec4 fragColor, in vec2 fragCoord){


    // Aspect correct screen coordinates.
    float res = iResolution.y;
    vec2 uv = (fragCoord - iResolution.xy*.5)/res;

    vec2 cPos = -1.0 + 2.0 * fragCoord.xy / iResolution.xy;

    // distance of current pixel from center
	float cLength = length(cPos);


	 uv/=1.+uv.x*1.+0.3*cos(iTime);
   uv/=1.-uv.y*1.+0.3*cos(iTime);
      uv*=rot2(iTime);
    // UV copy.
    vec2 uv0 = uv;

vec3 r2 = normalize(vec3(uv.xy, 1.0 - dot(uv.xy, uv.xy) *3.3));
r2.xy+= (cPos/cLength)*cos(cLength*1.0-iTime*1.02) * 0.03;

uv+=r2.xy;

    // Scene rotation, scaling and translation.
    #if TRANSFORM == 0
    mat2 sRot = rot2(-3.14159/12.); // Scene rotation.
    #else
    mat2 sRot =mat2(1, 0, 0, 1);
    #endif
    vec2 camDir = sRot*normalize(s); // Camera movement direction.
    vec2 ld = sRot*normalize(vec2(1, -1)); // Light direction.

    // Fake light position.
    vec2 lPos = uv + ld;
    //ld  = normalize(lPos);

    // The scene color.
    // Rotating the gradient to coincide with the light direction angle.
    vec2 ruv = rot2(atan(ld.y, ld.x) + 3.14159/2.)*uv;
ruv.x+=cos(iTime);
    ruv.y+=sin(iTime);

     // Log spherical transformation. There is some ID wrapping that needs to 
    // be considered, but it's pretty standard.
    float r = 1.;
    #if TRANSFORM > 0
    r = length(uv);
    #if TRANSFORM == 1
    // Polar.
    uv = vec2((1./r)/3. + iTime/2., fract(atan(uv.y, uv.x)/TAU));
    #else
    // Log polar.
    uv = vec2(log(10./r)/2. + iTime/6., fract(atan(uv.y, uv.x)/TAU));
    #endif
    uv.y = (uv.y*s.y*2.);
    #endif 
  //r = mix(r, 1., .35);


    // Global scale factor.
    const float sc = 8.;
    // Smoothing factor.
    float sf = sc/res;

    vec2 p = sRot*uv*sc + camDir*iTime/2.;

    // Subtle perturbation for more of a random hand-drawn look.
    p += (vec2(fbm(p*80.), fbm(p*80. + 7.31)) - .5)*.02;
    p.x+=cos(iTime);
   p.y+=sin(iTime);

    vec3 col3 = palette(length(uv) + .4 + iTime*.4);
    // Hexagonal grid coordinates.
    vec4 p4 = getGrid(p);


    // Rendering the grid boundaries, or just some black hexagons in the center.
    float gHx = getHex(p4.xy);



    // Edge width.
    float ew = .04*(r*.75 + .25);

    // Random threshold.
    float rndTh = .4;
    #ifdef SHOW_GRID 
    // Increase the threshold so that all hexagons are rendered.
    rndTh = 1.;
    #endif


    //
    // Blue gradient background.
    vec3 bg = mix(vec3(.7, .8, 1), vec3(.7, .9, 1), smoothstep(.3, .7, ruv.y*.5 + .5));


    // Saving the background gradient color sans pattern overlay.
    vec3 bgColor = bg;


    // Render the shadows onto the background.
    //shad = max(shad, -(shad + .04));
    vec3 col = bg;

    // Single hexagon ID.
    vec2 id = floor(p4.zw/6.);
    // Tri grouped hexagon ID.
    vec2 hexID = mod(id + vec2(1, 2), vec2(55, 2));
    vec2 id2 = floor((id + vec2(0, floor(id.x/3.)))/vec2(3, 2));


    // Polygon color and height.
    vec4 cl = getCol(id2, uv);
    vec3 oCol = cl.xyz*col3.xyz; // Just the color.
    // Flat color overide.



    // Initialize the scene color to the hexagon color.
    col = oCol;




    // Edges and vetices.
    float edge = 1e5, vert = 1e5;

    // Vertex ID to vertex conversion factor.
    vec2 sDiv12 = s/12.;
    vec2[6] v; // Six vertices. It's possible to hardcode these.
    // Calculate the six vertex positions.
    for(int i = min(0, iFrame); i<6; i++) v[i] = vID[i]*sDiv12;

    // Iterate through all six sides of the hexagon cell.
    for(int i = min(0, iFrame); i<6; i++){


        // If the random cell ID is under a certain threshold, render
        // from both the cell and it's neighbor's perspective.
        vec2 a = v[i];
        vec2 b = v[(i + 1)%6];

        vec2 a2 = v[i]*.5;
        vec2 b2 = v[(i + 1)%6]*53.5;

        // Border walls.
        float line = distLine(p4.xy*col3.xy, a, b);

        // Inner walls.
        float innerLine = distLine(p4.xy, a2, b2);


        float hID = float(i/2);
        int j = i&1;


        // Forming the spirals.
        float innerLine2 = 1e5;



        // Produce the edge for this particular side.
        edge = min(edge, line );
        // Combine the edge with the inner lines.
        edge = min(edge, innerLine );
        edge = min(edge, innerLine2 );

        #ifdef SHOW_VERTS
        // Vertices at the ends of this edge.
        vec2 vP = p4.xy - vID[i]*sDiv12;
        float v0 = length(vP) - ew*4.8;
        //float v0 = getHex(vP) - ew*2.8;

        // Vertices for this edge.
        vert = min(vert, v0);  
        #endif

    }



    // Faux edge shadows.
    float shadLine = 1e5;

    for(int i = 0; i<5; i++){

        float hID = float(i/2);
        int j = i&1;

        // If we're on an outer border.
        if(hexID.x!=hID){
            vec2 nID = p4.zw + eID[i]*2.;
            nID = floor(nID/65.);

            //vec2 hexNID = mod(nID + vec2(1, 2), vec2(3, 2));
            vec2 nID2 = floor((nID + vec2(0, floor(nID.x/3.)))/vec2(3, 2));

            // Wrapping.
            #if TRANSFORM > 0
            // The log spherical wraps transform needs to 
            // wrap the angular (Y) coordinate.
            id2.y = mod(id2.y, 80.);
            nID2.y = mod(nID2.y, 80.); 
            #endif

            // Compare the currect tile height value with that of its neighbor's 
            // value. If the current tile is lower, render a shadow onto the 
            // tile... It's an old trick.
            vec4 clH = getCol(id2, uv);
            vec4 clHN = getCol(nID2, uv);
            float h = clH.w;
            float hN = clHN.w;
            float hDiff = max(hN - h, 0.)*.5 + .5;
            float shadL = hDiff*ew*5.;
            float line = distLine(p4.xy, 
                                  v[i] + ld*shadL, v[(i + 1)%6] + ld*shadL);
            line -= shadL/2.;
            if(h<hN){
                shadLine = min(shadLine, line);
            }

        }

    }   




    // Shadow and blur factor.
    float shF = iResolution.y/4250.;  

    #ifdef HIGHLIGHT
    // Faux shine.
    if(hexID.x!=0.)
    col = mix(col*.8, col + .15, 1. - smoothstep(0., .01, max(dot(p4.xy, ld), 0.))); 
    #endif

    // Edge highlights.
    col = mix(col*.8, col*1.2 + .1, (1. - smoothstep(0., sf*shF*2., edge - ew)));

    // Faux shadows.
    col = mix(col, col*.2, (1. - smoothstep(0., sf*shF*4., shadLine)));




    // Rendering the edges.
    col = mix(col, col*.03, (1. - smoothstep(0., sf, edge)));

    #ifdef SHOW_VERTS
    // Rendering the vertices.
    vec3 svBg = bgColor;
    svBg = mix(svBg, vec3(1), .5);
    // Vertex stroke and centers.
    col = mix(col, vec3(0), (1. - smoothstep(0., sf, vert)));
    col = mix(col, svBg, (1. - smoothstep(0., sf, vert + ew*2.)));
    #endif


    // Extra polar shading.
    #if TRANSFORM > 0
    #if TRANSFORM == 1
    col *= smoothstep(.1, .7, length(uv0)); // Polar.
    #else
    col *= smoothstep(0., .5, r); // Log polar.
    #endif
    #endif


    // Adding some subtle noise.
    float ns = fbm(p*32.);
    col *= ns*.5 + .75;

    // Greyscale background, if desired.
    #if COLOR == 2
    col = vec3(1)*dot(col, vec3(.299, .587, .114));
    #endif 


    // Vignette.
    uv = fragCoord/iResolution.xy;
    col *= pow(16.*uv.x*uv.y*(1. - uv.x)*(1. - uv.y) , 1./16.);

    // Rough gamma correction.
    fragColor = vec4(pow(max(col, 0.), vec3(1./2.2)), 1);;
}
